# ==============================================================================# 048_RESOURCE_MANAGER.py# ==============================================================================import sqlite3import shutilimport platformimport osfrom pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")# ==============================================================================# RESOURCE TABLE# ==============================================================================cur.execute("""CREATE TABLE IF NOT EXISTS resources(    id INTEGER PRIMARY KEY AUTOINCREMENT,    collected_at TEXT,    hostname TEXT,    os_name TEXT,    python_version TEXT,    cpu_count INTEGER,    disk_total_gb REAL,    disk_used_gb REAL,    disk_free_gb REAL,    database_size_mb REAL,    services INTEGER,    plugins INTEGER,    scheduler_jobs INTEGER,    runtime_health REAL)""")conn.commit()# ==============================================================================# SISTEMA# ==============================================================================hostname = platform.node()os_name = platform.platform()python_version = platform.python_version()cpu_count = os.cpu_count() or 0usage = shutil.disk_usage(ROOT)disk_total = round(usage.total / (1024**3),2)disk_used = round((usage.total-usage.free)/(1024**3),2)disk_free = round(usage.free/(1024**3),2)db_size = round(DB.stat().st_size/(1024**2),3)# ==============================================================================# CONTADORES# ==============================================================================cur.execute("SELECT COUNT(*) FROM services")services = cur.fetchone()[0]cur.execute("SELECT COUNT(*) FROM plugins")plugins = cur.fetchone()[0]cur.execute("SELECT COUNT(*) FROM scheduler")scheduler = cur.fetchone()[0]cur.execute("""SELECT healthFROM runtime_monitorORDER BY id DESCLIMIT 1""")row = cur.fetchone()health = row["health"] if row else 0# ==============================================================================# SAVE# ==============================================================================cur.execute("""INSERT INTO resources(    collected_at,    hostname,    os_name,    python_version,    cpu_count,    disk_total_gb,    disk_used_gb,    disk_free_gb,    database_size_mb,    services,    plugins,    scheduler_jobs,    runtime_health)VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)""",(    datetime.now().isoformat(),    hostname,    os_name,    python_version,    cpu_count,    disk_total,    disk_used,    disk_free,    db_size,    services,    plugins,    scheduler,    health))conn.commit()# ==============================================================================# DASHBOARD# ==============================================================================cur.execute("""SELECT *FROM resourcesORDER BY id DESCLIMIT 1""")r = cur.fetchone()print("="*80)print("RESOURCE MANAGER")print("="*80)print(f"HOST..............: {r['hostname']}")print(f"SO................: {r['os_name']}")print(f"PYTHON............: {r['python_version']}")print(f"CPU...............: {r['cpu_count']} nÃºcleos")print()print(f"DISCO TOTAL.......: {r['disk_total_gb']:.2f} GB")print(f"DISCO USADO.......: {r['disk_used_gb']:.2f} GB")print(f"DISCO LIVRE.......: {r['disk_free_gb']:.2f} GB")print()print(f"DATABASE..........: {r['database_size_mb']:.3f} MB")print(f"SERVICES..........: {r['services']}")print(f"PLUGINS...........: {r['plugins']}")print(f"SCHEDULER.........: {r['scheduler_jobs']}")print(f"HEALTH............: {r['runtime_health']:.2f}%")print("="*80)conn.close()

